amówienia: {f.visible.length}</caption><thead><tr><th scope="col"><input type="checkbox" aria-label="Zaznacz wszystkie widoczne" checked={all} ref={element=>{if(element)element.indeterminate=some;}} onChange={event=>dispatch({type:"visibleSelectionChanged",ids:f.visible.map(order=>order.id),checked:event.currentTarget.checked})}/></th><th scope="col">Numer</th><th scope="col">Klient</th><th scope="col">Kwota</th><th scope="col">Status</th><th scope="col">Data</th></tr></thead><tbody>{f.visible.map(order=><tr key={order.id}><td><input type="checkbox" aria-label={"Zaznacz zamówienie "+order.id} checked={state.selectedIds.has(order.id)} onChange={()=>dispatch({type:"selectionToggled",id:order.id})}/></td><td>{order.id}</td><td>{order.customer}</td><MoneyCell grosze={order.totalGrosze}/><td>{order.status}</td><td><time dateTime={order.createdAt}>{new Intl.DateTimeFormat("pl-PL",{timeZone:"UTC"}).format(new Date(order.createdAt))}</time></td></tr>)}</tbody></table>{f.visible.length===0&&<p>Brak wyników.</p>}<section aria-label="Ostatnie zmiany"><h2>Ostatnie zmiany</h2><ol>{state.history.slice(0,5).map(entry=><li key={entry.orderId+entry.from+entry.to+entry.at}>#{entry.orderId}: {entry.from} → {entry.to} <time dateTime={entry.at}>{entry.at}</time></li>)}</ol></section></main>;}
export function OrdersApp(){return <CurrencyProvider><OrdersProvider orders={makeOrders()}><OrderScreen/></OrdersProvider></CurrencyProvider>;}

