export function formatMoney(grosze:number,currency:Currency):string{if(!Number.isSafeInteger(grosze)||grosze<0)throw RangeError("Kwota");const amount=currency==="PLN"?grosze/100:grosze/430;return new Intl.NumberFormat("pl-PL",{style:"currency",currency}).format(amount);}
export function makeOrders():Order[]{const customers=["Lumen sp. z o.o.","Jan Kowalski","Orbis S.A.","Maria Wiśniewska","Zenit"];return Array.from({length:30},(_,i)=>({id:1000+i,customer:customers[i%customers.length],totalGrosze:9900+(i*4721)%250000,status:STATUSES[i%STATUSES.length],createdAt:new Date(Date.UTC(2026,9,1+i%20)).toISOString()}));}
