export function makeOrders():Order[]{const customers=["Lumen sp. z o.o.","Jan Kowalski","Orbis S.A.","Maria Wiśniewska","Zenit"];return Array.from({length:30},(_,i)=>({id:1000+i,customer:customers[i%customers.length],totalGrosze:9900+(i*4721)%250000,status:STATUSES[i%STATUSES.length],createdAt:new Date(Date.UTC(2026,9,1+i%20)).toISOString()}));}
const date="2026-10-29T12:00:00Z";const data:readonly Order[]=[{id:0,customer:"Anna",totalGrosze:430,status:"NEW",createdAt:date},{id:1,customer:"Piotr",totalGrosze:860,status:"PAID",createdAt:date},{id:2,customer:"Kasia",totalGrosze:1290,status:"SHIPPED",createdAt:date}];const start=init(data);const after=ordersReducer(start,{type:"bulkTransitioned",ids:[0,1,2],to:"PAID",at:date});const undone=ordersReducer(after,{type:"bulkUndone"});console.log(formatMoney(430,"PLN").replace(/\s/g," "));

export const STATUSES=["NEW","PAID","SHIPPED","CANCELLED"] as const;export type Status=(typeof STATUSES)[number];export type Currency="PLN"|"EUR";export type Order={id:number;customer:string;totalGrosze:number;status:Status;createdAt:string};export type HistoryEntry={orderId:number;from:Status;to:Status;at:string};export const TRANSITIONS:Record<Status,readonly Status[]>={NEW:["PAID","CANCELLED"],PAID:["SHIPPED","CANCELLED"],SHIPPED:[],CANCELLED:[]};export function canTransition(from:Status,to:Status):boolean{return TRANSITIONS[from].includes(to);}
export function planTransition(orders:readonly Order[],ids:readonly number[],to:Status){const unique=new Set(ids);const affected=orders.filter(order=>unique.has(order.id)&&canTransition(order.status,to));const changedIds=new Set(affected.map(order=>order.id));return {affected,skippedIds:[...unique].filter(id=>!changedIds.has(id))};}
